INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 1, 5, 'go',
  'Peak rock-cut window. 19-29C, dry. 4-level Vishnukundina caves at year-best. 5m Anantha Padmanabha monolith.',
  'January is when the Undavalli rock-cut trip runs at year-best. Daytime 27-29C, nights 19-21C. The 4th-c CE Vishnukundina rock-cut caves (4 levels, Hindu+Buddhist+Jain syncretism, the 5m Anantha Padmanabha reclining Vishnu monolith — largest single-stone idol in India) at full access.',
  NULL,
  'Undavalli Caves in January is the version Andhra rock-cut-heritage scholars book first. Daytime 27-29C, nights 19-21C, rainfall under 30mm, humidity at 65 percent. The 4th-century CE Vishnukundina-era rock-cut caves — carved into a single sandstone hill across 4 vertical levels, 9km southwest of Vijayawada on the Krishna river south bank, ASI-protected — at full year-peak access. The cave complex started under the Vishnukundinas (4th-5th c CE) as Buddhist viharas, was later converted to Hindu use under the Vishnu-worshipping medieval kingdoms, and the second-floor sanctum holds the 5m-long Anantha Padmanabha Swamy reclining Vishnu — sculpted from a single block of sandstone, the largest single-stone idol in India. The cave levels show the syncretism of Hindu, Buddhist and Jain iconography across the four storeys, with the ground floor unfinished and the upper levels detailed with figural panels. ASI entry ₹15, 10am-5pm; Friday closures rare but verify. Combined with Amaravati (35km west) and Vijayawada heritage circuit, Undavalli works as a 2-day Krishna-basin trip.'
)
