INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 3, 4, 'go',
  'Last cool month. 23-33C. Cave interiors cool. Outdoor hill-steps approach compresses to mornings.',
  'March is the soft-landing month. Cave interiors hold 23-26C through day. Outdoor hill-step approach to the 4 levels compresses to 6-10am and 5-7pm. Vijayawada base rates 20 percent below February.',
  NULL,
  'March in Undavalli Caves is the transition month. Daytime 31-33C, nights 23-24C, humidity climbing to 70 percent, rainfall under 25mm. The cave interiors continue to hold 23-26C naturally year-round (the sandstone-rock mass acts as climate control) so the cave visit itself stays comfortable through the day, but the outdoor hill-step approach between the 4 vertical levels and the open-ground walk from the parking area to the base of the cave compresses to 6-10am and 5-7pm. The mid-day visit pattern shifts to: AC car retreat, brief outdoor walk to the cave, longer time inside, brief walk out — works cleanly with planning. The Anantha Padmanabha Swamy sanctum at peak photographic light through the morning slot. The Krishna river-side viewpoint from the cave hilltop at peak afternoon light. ASI entry ₹15. Hotel rates in Vijayawada base ease 20 percent off February: Novotel ₹6-8k, Gateway ₹7-9k, mid-bracket ₹2.5-3.5k. The last clean-value window before the April-May humidity-and-heat dome shifts the outdoor approach to dawn-only.'
)
