INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 4, 3, 'wait',
  'Pre-monsoon heat. 26-36C, humidity 75 percent. Cave interiors cool. Outdoor approach dawn-only.',
  'April pushes the outdoor approach to dawn only. Cave interiors hold their natural 23-26C and stay comfortable. Visit pattern: 7am AC car arrival, 90-min cave visit, 9am departure. Vijayawada base rates 30 percent below January.',
  'April pushes the trip into pre-monsoon stress for the outdoor approach. Cave interiors hold cool but the hill-step climb and parking-area walk become unsafe 10am-5pm. October-March is the proper window.',
  'April in Undavalli Caves is when the outdoor approach to the cave compresses to dawn only. Daytime 33-36C, nights 26-27C, humidity 75 percent, sea breeze unavailable inland. Pre-monsoon thunderstorms hit the last fortnight — short squalls that drop temperatures 3-4 degrees temporarily but raise humidity to 90 percent. The cave interiors continue to hold 23-26C naturally and stay comfortable through the day — the limiting factor is the 4-level vertical hill-step climb between the floors (open to the elements at the level-transitions) and the walk from parking to the cave base. The viable visit pattern in April: 7am AC car arrival, 90-minute cave visit including the Anantha Padmanabha sanctum and the 4-level syncretism circuit, 9am departure before peak heat. ASI entry remains ₹15, 10am-5pm but the early-arrival pattern depends on the morning gate timing — verify with ASI Undavalli office. Hotel rates in Vijayawada base run 25-30 percent below January: Novotel ₹5-7k, Gateway ₹6-8k. October-March is the proper window for a relaxed 2-3 hour cave visit shape.'
)
