INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 5, 2, 'wait',
  'Peak heat. 27-38C, humidity 78 percent. Cave interiors cool but outdoor approach unsafe most of day.',
  'May functions only as dawn AC-car visit. Cave interiors hold cool but the hill-step approach unsafe 8am-7pm. Pre-monsoon thunderstorms third week. October is dramatically better.',
  'May pushes the trip to dawn-only viable. Outdoor walks unsafe except 5-7am. October-March is the proper window for the relaxed multi-level cave circuit.',
  'May in Undavalli Caves is the brutal heat month for the outdoor approach. Daytime 36-38C, occasional 39-40C peaks the second-third week, nights 27-28C, humidity 78 percent — Vijayawada-area inland Krishna basin runs hot. Pre-monsoon thunderstorms hit the third and fourth week. The cave interiors continue to hold 23-26C naturally and remain comfortable — but the outdoor approach (parking-to-cave walk, the 4-level vertical hill-step transitions) becomes unsafe 8am-7pm. Visit viable only as 5:30-7:30am dawn AC-car shape with cave-entry by 6am (this works only if special-entry coordination with ASI Undavalli office is arranged — standard 10am opening makes the trip impractical in peak summer). The Anantha Padmanabha Swamy sanctum, the 4-level Hindu-Buddhist-Jain syncretism panels and the Krishna river-side viewpoint all accessible but the trip shape collapses. Hotel rates in Vijayawada base at year-low: Novotel ₹4-6k, Gateway ₹5-7k. Wait for late October.'
)
