INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 6, 2, 'wait',
  'SW monsoon arrives. 26-33C, 150-200mm. Cave interiors cool. Outdoor approach rain-interrupted.',
  'June is monsoon arrival. Cave interiors hold their natural 23-26C and stay comfortable. Outdoor approach rain-interrupted. October is materially cleaner.',
  'June is the SW monsoon arrival. Cave interiors stay cool but outdoor approach gets rain-interrupted. October delivers a cleaner trip shape.',
  'June in Undavalli Caves is the southwest monsoon arrival on the Krishna basin. The SW current hits the AP coast around June 1-5 — IMD declares formal monsoon onset annually. Rainfall jumps from May''s 50mm to 150-200mm across 14-16 wet days; the Krishna river volume builds through June. Daytime 30-33C feels cooler against May but 86 percent humidity and intermittent sustained downpours close down the outdoor approach to the cave. The cave interiors continue to hold 23-26C naturally — humidity inside rises but temperature stays comfortable. The outdoor approach (parking-to-cave walk, the level-transition open-air sections) rain-interrupted. ASI entry continues 10am-5pm with intermittent visitor traffic. The Anantha Padmanabha Swamy sanctum at full access. Hotel rates in Vijayawada base at year-low: Novotel ₹4-6k, Gateway ₹5-7k. Wait for late October when the rain-window pattern eases.'
)
