INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 7, 2, 'wait',
  'Peak SW monsoon. 26-31C, 200-250mm. Krishna at flood-watch. Cave interiors viable. Outdoor closed.',
  'July is monsoon peak. Cave interiors continue to hold cool 23-26C. Outdoor approach rain-blocked. Visitor traffic minimal. Wait for October.',
  'July is peak monsoon. Outdoor approach closed by rain. Cave interiors stay cool but the trip shape collapses. October is materially cleaner.',
  'July in Undavalli Caves is the wettest stretch. Rainfall 200-250mm across 18-20 wet days, daytime 28-31C, humidity 88 percent. The Krishna river runs at flood-watch level through the month — Undavalli sits 6km from the river ghat and the surrounding ground gets seasonally flooded. The cave interiors continue to hold 23-26C naturally and stay technically accessible — but the outdoor approach (parking-to-cave walk, the level-transition sections) becomes rain-blocked. ASI entry continues 10am-5pm but visitor traffic falls to minimal. The Anantha Padmanabha Swamy sanctum stays at full access for the few visitors who arrive. Hotel rates in Vijayawada base at year-low: Novotel ₹4-6k, Gateway ₹5-7k. The trip you came for — relaxed multi-level cave circuit, Krishna river-side viewpoint from the hilltop, syncretic-iconography appreciation — needs the October-March window for full access. Wait.'
)
