INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 8, 2, 'wait',
  'Monsoon continues. 26-31C, 150-200mm. Cave interiors viable. Outdoor approach rain-interrupted.',
  'August holds July''s pattern. 150-200mm rain. Cave interiors stay cool but outdoor approach gets rain-interrupted. October is materially cleaner.',
  'August is monsoon continuation. Outdoor approach closed by rain. Cave interiors stay cool but the trip shape collapses. October is materially cleaner.',
  'August in Undavalli Caves stays in monsoon mode across the Krishna basin. Rainfall 150-200mm across 16-18 wet days, daytime 28-31C, humidity 87 percent. The Krishna river continues to run at flood-watch level. The cave interiors continue to hold 23-26C naturally and stay technically accessible. The outdoor approach remains rain-interrupted. ASI entry continues 10am-5pm with minimal visitor traffic. The Anantha Padmanabha Swamy sanctum at full access for visitors who arrive. Hotel rates in Vijayawada base at year-low: Novotel ₹4-6k, Gateway ₹5-7k. The Krishna Pushkaralu (every 12 years at Vijayawada, last August 2016 — 2016 was the major year, next is 2028, NOT 2026) is the broader Krishna-basin defining event; Undavalli sits along the Vijayawada-Pushkaralu pilgrimage route but 2026 is not a Pushkaralu year. Cyclone-track watch via mausam.imd.gov.in continues — September-October is the peak Bay of Bengal cyclone window. The next clean window is mid-October.'
)
