INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 9, 3, 'go',
  'SW monsoon retreat. 25-31C, 100-150mm. Cave interiors cool. Outdoor approach returns last week.',
  'September is the recovery month. SW monsoon retreats through the second half. Outdoor approach returns to walkability the last week. Cave interiors continue to hold cool 23-26C. Cyclone-watch active.',
  NULL,
  'September in Undavalli Caves is the recovery month. Rainfall 100-150mm across 11-13 wet days, daytime 28-31C, humidity 80 percent dropping to 75 by month-end. The southwest monsoon retreats from the AP coast around September 25-30. The cave interiors continue to hold 23-26C naturally and remain comfortable through the day. The outdoor approach (parking-to-cave walk, the level-transition sections) returns to comfortable walkability through the last week as ground dries. ASI entry continues 10am-5pm. The Anantha Padmanabha Swamy sanctum at full access. The 4-level syncretism circuit walkable from the second half onward. September-October is the peak Bay of Bengal cyclone window — Hudhud-class storms can form starting mid-September; IMD watch via mausam.imd.gov.in is mandatory. Hotel rates in Vijayawada base climb 15-20 percent versus August lows: Novotel ₹5-7k, Gateway ₹6-8k, mid-bracket ₹2-3k. The October 15 onward window is dramatically cleaner for first-time visitors but late-September works for those wanting quieter visitor density.'
)
