INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 10, 4, 'go',
  'Season opens. 23-31C. Cyclone-watch first fortnight. Outdoor approach returns. Dussehra at Kanaka Durga (8km).',
  'October is the season opener. First 10-15 days carry cyclone-watch (Hudhud anniversary Oct 12). Beyond that, outdoor approach at full walkability. Cave interiors at peak. Dussehra at Kanaka Durga (8km, Vijayawada) is the regional anchor. Rates 25 percent below January.',
  NULL,
  'October in Undavalli Caves is the proper return to coherent. Rainfall drops to 100-150mm with the bulk falling in the first ten days; from October 15 onward the trip flips into clean cave-and-hilltop mode. Daytime 28-31C, humidity falling from 80 to 73 percent. The first fortnight carries the Bay of Bengal cyclone risk (Hudhud landed Vizag Oct 12, 2014; Phailin hit Odisha-AP coast Oct 12, 2013) — IMD watch via mausam.imd.gov.in mandatory October 5-20. Beyond that, the outdoor approach to the cave (parking-to-cave walk, the 4-level vertical hill-step transitions) returns to full walkability. The cave interiors continue to hold 23-26C naturally. The Anantha Padmanabha Swamy sanctum and the 4-level syncretism circuit at full access. The Krishna river-side viewpoint from the cave hilltop returns to clear-weather afternoon light. Dussehra / Sharadiya Navratri at Kanaka Durga Vijayawada (8km, the regional anchor temple) — 9 nights, 200,000+ daily pilgrim density at peak. Strong call for first-time visitors who want full heritage circuit minus December-January crunch.'
)
