INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 11, 5, 'go',
  'Peak window opens. 21-30C, sub-50mm rain. Cave interiors cool. Outdoor at peak. Karthika Masam.',
  'November is the year''s second-peak month. Rainfall under 50mm. Outdoor approach at peak walkability. Cave interiors cool. Karthika Masam brings deepam lighting at temples across Vijayawada (8km). Rates 25 percent below December.',
  NULL,
  'November in Undavalli Caves is the year''s second-peak month behind January. Rainfall under 50mm, daytime 27-30C, nights 21-22C, humidity dropping below 70 percent. The Bay of Bengal cyclone risk falls sharply after October 25. The outdoor approach (parking-to-cave walk, the 4-level vertical hill-step transitions) at full walkability through the day. The cave interiors continue to hold 23-26C naturally — paired with cool 27-30C outside, the relaxed multi-hour visit pattern returns. The Anantha Padmanabha Swamy sanctum and the 4-level Hindu-Buddhist-Jain syncretism circuit at full access with peak photographic light. The Krishna river-side viewpoint from the cave hilltop at year-peak clarity. Karthika Masam (mid-November to mid-December) brings mass deepam lighting at temples across the Vijayawada area (Kanaka Durga, Amaravateeswara Pancharama, smaller Shiva temples); Undavalli itself isn''t a major Karthika site but the broader Krishna basin trip pattern absorbs the deepam visits as evening anchors. Hotel rates in Vijayawada base climb to 80 percent of January peak: Novotel ₹7-10k, Gateway ₹8-11k, mid-bracket ₹2.5-4k. Strong call for first-time visitors.'
)
