INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES (
  'undavalli-caves', 12, 5, 'go',
  'Peak season. 20-29C, dry. Christmas-NYE rates 1.5-2x in Vijayawada base. Late-Dec cyclone outliers.',
  'December is when the Undavalli rock-cut trip runs at full capacity. Daytime 27-29C, sub-25mm rain. Cave interiors and outdoor approach both at peak. Christmas-NYE rates 1.5-2x in Vijayawada base hotels. Late-season cyclones possible.',
  NULL,
  'December in Undavalli Caves is the operational peak. Daytime 27-29C, nights 20-21C, rainfall under 25mm. The cave interiors hold 23-26C naturally and the cool-outside-cool-inside pairing is the year''s best combination for relaxed multi-hour viewing. The Anantha Padmanabha Swamy reclining Vishnu monolith (5m, largest single-stone idol in India, 2nd-floor sandstone sanctum) at year-peak photographic light through the morning. The 4-level Hindu-Buddhist-Jain syncretism circuit walkable cleanly across all storeys. The Krishna river-side viewpoint from the cave hilltop at year-peak clarity. ASI entry remains ₹15, 10am-5pm. Recent late-season cyclones — Mandous (December 2022); Michaung (December 5-6, 2023, made landfall near Nellore, brushed the Krishna basin with heavy rain) — are reminders that Bay of Bengal cyclogenesis extends into December. IMD watch via mausam.imd.gov.in standard. Combined with Amaravati (35km) and the Vijayawada heritage circuit (Kanaka Durga, Bhavani Island, Prakasam Barrage) Undavalli works as a 2-3 day Krishna-basin trip.'
)
